variables.code:
x := 10;
# Delayed evaluation or defining a function/expression
y := 'x^2';

data_types.code:
int_val := 42;
float_val := 3.14;
frac_val := 3 / 4;
comp_val := 1 + 2*I;
str_val := "string";
sym := a + b; # Symbolic expression

operators.code:
2 + 3 * 4;
2 ^ 10;
17 mod 5;

# Non-commutative multiplication for matrices
A . B;

conditionals.code:
if x > 0 then
    print("Positive");
elif x < 0 then
    print("Negative");
else
    print("Zero");
end if;

for_loop.code:
for i from 1 to 10 do
    print(i^2);
end do;

# Over elements of a list
for elem in [1, 2, 3] do
    print(elem);
end do;

while_loop.code:
count := 0;
while count < 5 do
    print(count);
    count := count + 1;
end do;

functions.code:
# Using proc
calc_mean := proc(L::list)
    if numelems(L) = 0 then return undefined; end if;
    return add(x, x in L) / numelems(L);
end proc;

# Arrow operator for anonymous/simple functions
f := x -> x^2;

maps.code:
T := table(["a" = 1, "b" = 2]);

# Accessing
val := T["a"];

# Assigning new key
T["c"] := 3;

error_handling.code:
try
    res := 1 / 0;
catch "numeric exception: division by zero":
    print("Cannot divide by zero");
catch:
    print("An unknown error occurred");
finally
    print("Cleanup");
end try;
